typedef unsigned long long ull;
#define BITS 64
#define WORDS ((MAXW + BITS - 1) / BITS)

ull reachable[WORDS];
ull temp[WORDS];

void set_bit(ull *bits, int pos) {
    bits[pos / BITS] |= (1ULL << (pos % BITS));
}

int get_bit(ull *bits, int pos) {
    return (bits[pos / BITS] >> (pos % BITS)) & 1ULL;
}

void or_bits(ull *dest, ull *src) {
    for (int i = 0; i < WORDS; i++) {
        dest[i] |= src[i];
    }
}

void shift_left(ull *dest, ull *src, int shift) {
    int word_shift = shift / BITS;
    int bit_shift = shift % BITS;
    memset(dest, 0, sizeof(ull) * WORDS);
    if (bit_shift == 0) {
        for (int i = 0; i + word_shift < WORDS; i++) {
            dest[i + word_shift] = src[i];
        }
    } else {
        for (int i = 0; i < WORDS; i++) {
            if (i + word_shift < WORDS) {
                dest[i + word_shift] |= src[i] << bit_shift;
            }
            if (i + word_shift + 1 < WORDS && bit_shift > 0) {
                dest[i + word_shift + 1] |= src[i] >> (BITS - bit_shift);
            }
        }
    }
}

void shift_right(ull *dest, ull *src, int shift) {
    int word_shift = shift / BITS;
    int bit_shift = shift % BITS;
    memset(dest, 0, sizeof(ull) * WORDS);
    if (bit_shift == 0) {
        for (int i = word_shift; i < WORDS; i++) {
            dest[i - word_shift] = src[i];
        }
    } else {
        for (int i = word_shift; i < WORDS; i++) {
            dest[i - word_shift] |= src[i] >> bit_shift;
            if (i - word_shift - 1 >= 0 && bit_shift > 0) {
                dest[i - word_shift - 1] |= src[i] << (BITS - bit_shift);
            }
        }
    }
}

