        // The maximum needed weight is bounded by max amount + max weight sum
        long maxAmount = 0;
        for (long a : amounts) maxAmount = Math.max(maxAmount, a);
        long maxWeightSum = 0;
        for (long w : weights) maxWeightSum += w;
        long upperBound = maxAmount + maxWeightSum + 1;

        for (long addWeight = 1; addWeight <= upperBound; addWeight++) {
            // Create new set with added weight
            long[] newWeights = Arrays.copyOf(weights, n + 1);
            newWeights[n] = addWeight;

            Set<Long> newPossible = new HashSet<>();
            computePossible(newWeights, 0, 0, newPossible);

            boolean canMeasureAll = true;
            for (long amount : amounts) {
                if (!newPossible.contains(amount)) {
                    canMeasureAll = false;
                    break;
                }
            }

            if (canMeasureAll) {
                System.out.println(addWeight);
                return;
            }
        }

        System.out.println(-1);
    }

    // Recursive function to compute all possible sums using weights with signs -1, 0, 1
    private static void computePossible(long[] weights, int idx, long currentSum, Set<Long> possible) {
        if (idx == weights.length) {
            possible.add(Math.abs(currentSum));
            return;
        }
        // Place weight on same plate as chemical (add)
        computePossible(weights, idx + 1, currentSum + weights[idx], possible);
        // Place weight on opposite plate (subtract)
        computePossible(weights, idx + 1, currentSum - weights[idx], possible);
        // Don't use weight
        computePossible(weights, idx + 1, currentSum, possible);
    }
