    static boolean[] reachable(int[] w, int sumW) {
        int size = 2 * sumW + 1;
        boolean[] dp = new boolean[size];
        int off = sumW;
        dp[off] = true; // difference 0

        for (int weight : w) {
            boolean[] next = new boolean[size];
