                if (!dp[i]) continue;
                // don't use
                next[i] = true;
                // put on left
                if (i + weight < size) next[i + weight] = true;
                // put on right
                if (i - weight >= 0) next[i - weight] = true;
            }
            dp = next;
        }
        return dp;
    }

    static boolean worksWithAdded(boolean[] base, int sumW, int[] queries, int x) {
        int newSum = sumW + x;
        int offOld = sumW;

