            int need1 = q - x;
            if (!ok && Math.abs(need1) <= sumW && base[offOld + need1]) ok = true;

            // Added weight on opposite side: d - x = q => d = q + x
            int need2 = q + x;
            if (!ok && Math.abs(need2) <= sumW && base[offOld + need2]) ok = true;

            if (!ok) return false;
        }
        return true;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
